// One line per page. Leave out appears/disappears to get the changed lines instead.
// start/end: only watch the text between these two phrases. ignore: a regex for parts that change every time (dates, counters).
const PAGES = [
  { name: 'Keyboard back in stock', url: 'https://shop.example.com/products/keyboard', appears: 'Add to cart' },
  { name: 'Tickets on sale', url: 'https://example.com/tour', disappears: 'Sold out' },
  { name: 'Docs changelog', url: 'https://example.com/changelog', start: 'Release notes', end: 'Older releases', ignore: 'Last updated .*' },
];
return PAGES.map(p => ({ json: p }));

// Compares each page with the last check. State is kept in the workflow's static data (only saved in Active/production runs).
const MAX_LINES = 12, FAIL_ALERT_AFTER = 3;
const mem = $getWorkflowStaticData('global'); mem.pages = mem.pages || {};
const watches = $('Pages to watch').all().map(i => i.json);
const pages = $input.all();
const BLOCK = 'p|div|br|li|tr|td|th|h[1-6]|section|article|header|footer|option|dt|dd|blockquote|pre|button|label|title';
const ENT = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ', '#39': "'" };
const toLines = (raw, w) => {
  let t = String(raw || '')
    .replace(/<!--[\s\S]*?-->/g, '')
    .replace(/<(script|style|noscript|template|svg|head)\b[\s\S]*?<\/\1\s*>/gi, '\n')
    .replace(new RegExp(`<\\/?(${BLOCK})\\b[^>]*>`, 'gi'), '\n')
    .replace(/<[^>]+>/g, '')
    .replace(/&(#\d+|#x[0-9a-f]+|[a-z]+\d*);/gi, (m, e) => e[0] === '#' ? String.fromCodePoint(e[1].toLowerCase() === 'x' ? parseInt(e.slice(2), 16) : parseInt(e.slice(1), 10)) : (ENT[e.toLowerCase()] ?? m));
  let lines = t.split('\n').map(l => l.replace(/\s+/g, ' ').trim()).filter(Boolean);
  let text = lines.join('\n');
  if (w.start && text.includes(w.start)) text = text.split(w.start).slice(1).join(w.start);
  if (w.end && text.includes(w.end)) text = text.split(w.end)[0];
  lines = text.split('\n').map(l => l.trim()).filter(Boolean);
  if (w.ignore) { const rx = new RegExp(w.ignore, 'gi'); lines = lines.map(l => l.replace(rx, '').trim()).filter(Boolean); }
  return lines;
};
const has = (lines, p) => lines.join('\n').toLowerCase().includes(String(p).toLowerCase());
const out = [];
watches.forEach((w, i) => {
  const name = w.name || w.url, key = w.url + '|' + (w.appears || '') + '|' + (w.disappears || '');
  const old = mem.pages[key] || {};
  const res = pages[i] ? pages[i].json : {};
  const raw = typeof res.data === 'string' ? res.data : '';
  if (res.error || !raw) {
    const fails = (old.fails || 0) + 1;
    mem.pages[key] = { ...old, fails };
    if (fails === FAIL_ALERT_AFTER) out.push({ json: { content: `⚠️ **${name}** could not be loaded ${fails} checks in a row\n${w.url}` } });
    return;
  }
  const lines = toLines(raw, w);
  const now = { lines: lines.slice(0, 1500), fails: 0 };
  if (w.appears || w.disappears) {
    const hit = (w.appears ? has(lines, w.appears) : true) && (w.disappears ? !has(lines, w.disappears) : true);
    now.hit = hit; delete now.lines;
    if ('hit' in old && hit && !old.hit) {
      const why = [w.appears && `"${w.appears}" is now on the page`, w.disappears && `"${w.disappears}" is gone`].filter(Boolean).join(' and ');
      out.push({ json: { content: `🔔 **${name}**: ${why}\n${w.url}` } });
    }
    mem.pages[key] = now; return;
  }
  mem.pages[key] = now;
  if (!old.lines) return; // first run: just remember
  const before = new Set(old.lines), after = new Set(now.lines);
  const added = [...new Set(now.lines.filter(l => !before.has(l)))]; // lines that only moved don't count
  const removed = [...new Set(old.lines.filter(l => !after.has(l)))];
  if (!added.length && !removed.length) return;
  const body = [];
  for (const [s, xs] of [['+', added], ['-', removed]]) {
    body.push(...xs.slice(0, MAX_LINES).map(x => `${s} ${x.slice(0, 200)}`));
    if (xs.length > MAX_LINES) body.push(`${s} ...and ${xs.length - MAX_LINES} more`);
  }
  out.push({ json: { content: `🔔 **${name}** changed (${added.length} added, ${removed.length} removed)\n${w.url}\n${body.join('\n')}`.slice(0, 1990) } });
});
return out;
